def build_demo_corpus() -> List[Document]:
    """A small fictional corpus about the 'Acme Cloud Platform'."""
    return [
        Document(
            "The Acme Python SDK is the fastest way to integrate the Acme Cloud Platform "
            "into your application. Install it with pip install acme-sdk. After "
            "installation, create an API key in the Acme console and set the "
            "ACME_API_KEY environment variable. The quickstart example below uploads "
            "your first file in under ten lines of code. The SDK requires Python 3.9 or "
            "newer and supports macOS, Windows, and Linux.",
            {"title": "Getting Started with the Acme Python SDK", "category": "technical",
             "tags": ["python", "sdk", "installation", "quickstart"],
             "source": "docs.acme.dev", "date": "2025-01-10"},
        ),
